/**
 * dsh-provider-usage — 适配器管理路由（GET /adapters.json, POST /adapters/select, inspect, add）。
 *
 * 加载校验与路径准入经 AdapterRoutesContext 注入（#768 B2：不直引 registry 门面值边；
 * 组合根已绑定 registry 实例，类型经门面以 type 复用）。
 */
import type { IncomingMessage, ServerResponse } from "node:http";
import { basename } from "node:path";
import type { Context } from "@deepseek-ai/cordis";
import type { WebRoute } from "@deepseek-ai/dsh-host-webserver";
import {
  guardLoopbackMethod,
  readJsonBodyOutcome,
  writeJson,
} from "../../../../../shared/host-utils.js";
import { ADAPTER_CONTRACT_VERSION, type UsageStatsAdapter } from "../../shared/interface.ts";
import type { StatsService } from "../pipeline/interface.ts";
import type { UserAdapterRecord } from "../registry/interface.ts";

export interface AdapterRoutesContext {
  ctx: Context;
  statsService: StatsService;
  ensureHotReload: (file: string) => Promise<void>;
  /**
   * 路径准入注入（#768 B2：不直引 registry 门面值边；组合根供给，禁穿越口径留 registry 域）。
   */
  resolveAdapterFile: (input: unknown) => string | undefined;
  /**
   * 加载校验注入（#768 B2：不直引 registry 门面值边；组合根已绑定 registry 实例）。
   */
  loadAdapterChecked: (
    file: string,
  ) => Promise<
    { ok: true; adapter: UsageStatsAdapter } | { ok: false; code: string; detail: string }
  >;
}

export function handleAdapters(
  req: IncomingMessage,
  res: ServerResponse,
  context: AdapterRoutesContext,
): void {
  if (!guardLoopbackMethod(req, res, ["GET"])) return;
  const { ctx, statsService } = context;
  const snap = statsService.registry.snapshot();

  let modelProviders: string[] = [];
  try {
    const llm = (ctx as { llm?: { listProviders?: () => unknown } }).llm;
    if (typeof llm?.listProviders === "function") {
      const listed = llm.listProviders();
      if (Array.isArray(listed)) {
        modelProviders = listed
          .map((i) => (i as { id?: unknown } | null)?.id)
          .filter((id): id is string => typeof id === "string" && id !== "");
      }
    }
  } catch {
    // 回落空数组
  }

  writeJson(res, 200, {
    version: ADAPTER_CONTRACT_VERSION,
    host: snap.infos.map((i) => ({
      name: i.name,
      label: i.label,
      providers: i.providers,
      source: i.source,
      file: i.file !== undefined ? basename(i.file) : null,
      enabled: i.enabled,
    })),
    enabled: snap.enabled,
    errors: snap.errors.map((e) => ({ key: e.key, at: e.at, kind: e.kind, message: e.message })),
    modelProviders,
  });
}

export async function handleSelect(
  req: IncomingMessage,
  res: ServerResponse,
  context: AdapterRoutesContext,
): Promise<void> {
  if (!guardLoopbackMethod(req, res, ["POST"])) return;
  const { statsService } = context;

  const outcome = await readJsonBodyOutcome(req);
  if (outcome.kind !== "json") return writeJson(res, 400, { error: "bad-json" });
  const body = outcome.value as Record<string, unknown>;

  const provider = typeof body.provider === "string" ? body.provider : "";
  const clearing = body.adapterName === null;
  const adapterName = typeof body.adapterName === "string" ? body.adapterName : "";
  if (
    !clearing &&
    (provider.length === 0 ||
      adapterName.length === 0 ||
      provider.length > 128 ||
      adapterName.length > 128)
  ) {
    return writeJson(res, 400, { error: "invalid provider/adapterName" });
  }

  const ok = statsService.registry.select(provider, clearing ? null : adapterName);
  if (!ok) return writeJson(res, 404, { error: "adapter not found" });

  statsService.purgeAllCaches();
  if (!clearing) statsService.warmupProviders([provider]);

  if (clearing) statsService.scheduleWriteAdapterState({ [provider]: null });
  else statsService.scheduleWriteAdapterState();

  writeJson(res, 200, { ok: true, provider, adapterName: clearing ? null : adapterName });
}

export async function handleInspect(
  req: IncomingMessage,
  res: ServerResponse,
  context: AdapterRoutesContext,
): Promise<void> {
  if (!guardLoopbackMethod(req, res, ["POST"])) return;

  const outcome = await readJsonBodyOutcome(req);
  if (outcome.kind !== "json") return writeJson(res, 400, { error: "bad-json" });
  const body = outcome.value as Record<string, unknown>;

  const file = context.resolveAdapterFile(body.file);
  if (file === undefined) {
    return writeJson(res, 400, {
      error: "invalid-file",
      detail: "文件不存在/不可读，或路径未规整（禁穿越）",
    });
  }

  const loaded = await context.loadAdapterChecked(file);
  if (!loaded.ok) {
    return writeJson(res, 422, { error: loaded.code, detail: loaded.detail });
  }

  const { adapter } = loaded;
  writeJson(res, 200, {
    ok: true,
    adapter: {
      name: adapter.name,
      label: adapter.label ?? adapter.name,
      providers: adapter.providers,
      version: adapter.version,
    },
    file: basename(file),
  });
}

export async function handleAdd(
  req: IncomingMessage,
  res: ServerResponse,
  context: AdapterRoutesContext,
): Promise<void> {
  if (!guardLoopbackMethod(req, res, ["POST"])) return;
  const { statsService, ensureHotReload } = context;

  const outcome = await readJsonBodyOutcome(req);
  if (outcome.kind !== "json") return writeJson(res, 400, { error: "bad-json" });
  const body = outcome.value as Record<string, unknown>;

  const file = context.resolveAdapterFile(body.file);
  if (file === undefined) {
    return writeJson(res, 400, {
      error: "invalid-file",
      detail: "文件不存在/不可读，或路径未规整（禁穿越）",
    });
  }

  const loaded = await context.loadAdapterChecked(file);
  if (!loaded.ok) {
    return writeJson(res, 422, { error: loaded.code, detail: loaded.detail });
  }

  const { adapter } = loaded;
  if (statsService.registry.hasName(adapter.name)) {
    return writeJson(res, 409, {
      error: "duplicate-name",
      detail: `适配器 name 已存在：${adapter.name}`,
    });
  }

  if (!statsService.registry.register(adapter, "user-file", file)) {
    return writeJson(res, 422, {
      error: "invalid-adapter",
      detail: "契约校验失败（version/name/providers/fetchData/formatCapsule/formatPanel）",
    });
  }

  const rec: UserAdapterRecord = {
    id: adapter.name,
    label: adapter.label ?? adapter.name,
    providers: adapter.providers,
    file,
  };
  await statsService.persistUserAdapter(rec);
  await ensureHotReload(file);

  statsService.purgeAllCaches();
  statsService.warmupProviders(adapter.providers);
  statsService.scheduleWriteAdapterState();

  writeJson(res, 200, {
    ok: true,
    adapter: {
      name: adapter.name,
      label: adapter.label ?? adapter.name,
      providers: adapter.providers,
      file: basename(file),
    },
    enabled: statsService.registry.snapshot().enabled,
  });
}

export function createAdapterRoutes(
  routes: { adapters: string; select: string; inspect: string; add: string },
  context: AdapterRoutesContext,
): WebRoute[] {
  return [
    {
      kind: "exact",
      path: routes.adapters,
      handler: (req, res) => handleAdapters(req, res, context),
    },
    {
      kind: "exact",
      path: routes.select,
      handler: (req, res) => handleSelect(req, res, context),
    },
    {
      kind: "exact",
      path: routes.inspect,
      handler: (req, res) => handleInspect(req, res, context),
    },
    {
      kind: "exact",
      path: routes.add,
      handler: (req, res) => handleAdd(req, res, context),
    },
  ];
}

/**
 * dsh-provider-usage — 用量统计与历史面板路由（GET /stats, GET /history）。
 */
import type { IncomingMessage, ServerResponse } from "node:http";
import type { WebRoute } from "@deepseek-ai/dsh-host-webserver";
import { guardLoopbackMethod, writeJson } from "../../../../../shared/host-utils.js";
import { ADAPTER_CONTRACT_VERSION } from "../../shared/interface.ts";
import type { StatsService } from "../pipeline/interface.ts";

export interface StatsRoutesContext {
  statsService: StatsService;
}

export async function handleStats(
  req: IncomingMessage,
  res: ServerResponse,
  ctx: StatsRoutesContext,
): Promise<void> {
  if (!guardLoopbackMethod(req, res, ["GET"])) return;
  const { statsService } = ctx;
  const url = new URL(req.url ?? "/", "http://localhost");
  const prov = url.searchParams.get("provider") ?? statsService.config.provider;
  const controller = new AbortController();
  let settled = false;

  const finish = (status: number, body: unknown): void => {
    if (settled) return;
    settled = true;
    if (!res.destroyed && !res.writableEnded) writeJson(res, status, body);
  };

  if (typeof res.on === "function") {
    res.on("close", () => {
      if (!res.writableEnded) controller.abort();
    });
  }

  try {
    const result = await statsService.getStats(prov, controller.signal);
    finish(200, {
      plugin: "dsh-provider-usage",
      version: ADAPTER_CONTRACT_VERSION,
      provider: result.provider,
      adapterName: result.adapterName,
      status: result.status,
      capsuleHtml: result.capsuleHtml,
      ok: result.ok,
      configured: result.configured,
      reason: result.reason,
      error: result.error,
      fetchedAt: result.fetchedAt,
      adapterVersion: 0,
    });
  } catch {
    finish(504, { error: "stats timeout" });
  }
}

export async function handleHistory(
  req: IncomingMessage,
  res: ServerResponse,
  ctx: StatsRoutesContext,
): Promise<void> {
  if (!guardLoopbackMethod(req, res, ["GET"])) return;
  const { statsService } = ctx;
  const url = new URL(req.url ?? "/", "http://localhost");
  const prov = url.searchParams.get("provider") ?? statsService.config.provider;
  const entry = statsService.registry.getEntry(prov);

  if (entry === undefined) {
    const code = statsService.registry.hasCandidates(prov) ? "no-enabled-adapter" : "no-adapter";
    return writeJson(res, 200, {
      ok: false,
      plugin: "dsh-provider-usage",
      version: ADAPTER_CONTRACT_VERSION,
      provider: prov,
      adapterName: null,
      panelHtml: null,
      error: null,
      reason: code,
      range: { start: 0, end: 0 },
    });
  }

  const days = Number(url.searchParams.get("days"));
  const end = Date.now();
  const start =
    Number.isFinite(days) && days > 0
      ? end - Math.min(Math.round(days), statsService.config.maxAgeDays) * 86400000
      : end - 86400000;

  // D7：面板渲染管道整体下沉 StatsService.getPanelResult（命中/miss/失败不写/并发单飞
  // 均在服务方法内），路由不再直读写 panelCache 内部。
  const result = await statsService.getPanelResult(prov, entry, { start, end });

  writeJson(res, 200, {
    ok: result.error === undefined,
    plugin: "dsh-provider-usage",
    version: ADAPTER_CONTRACT_VERSION,
    provider: prov,
    adapterName: entry.name,
    panelHtml: result.panelHtml,
    error: result.error ?? null,
    range: { start, end },
  });
}

export function createStatsRoutes(
  routes: { stats: string; history: string },
  ctx: StatsRoutesContext,
): WebRoute[] {
  return [
    {
      kind: "exact",
      path: routes.stats,
      handler: (req, res) => handleStats(req, res, ctx),
    },
    {
      kind: "exact",
      path: routes.history,
      handler: (req, res) => handleHistory(req, res, ctx),
    },
  ];
}

