  });

  it("候选键 <= lastRun → 已扣期", () => {
    expect(allRecorded).toEqual([]);
  });

  it("lastRun 更晚 → 该期跳过", () => {
    expect(laterRecorded.some((d) => d.period === "daily")).toBeFalsy();
  });

  it("新锚点候选键 > lastRun → 补跑（未记录期同补）", () => {
